//! E2E payload encryption (federation P3) — zero-handshake PSK channels over relay hops.
//!
//! Key hierarchy:
//! - `e2e_key` — a random 32-byte master key generated by the issuer at issuance and stored
//!   encrypted in the DB. It travels to the consumer ONLY inside the share link (`ek`), never
//!   through the relay. The auth token is a separate secret (the relay legitimately sees it at
//!   the entry hop) and is NOT key material — a relay can no longer derive the E2E key from the
//!   token it authenticates against, so forwarded envelopes stay opaque to it.
//! - `chan_key = HKDF-SHA256(ikm = e2e_key, salt = chan_salt, info = "chan")` — a fresh 16-byte
//!   random salt per channel (carried inside the sealed Open blob) guarantees zero nonce reuse
//!   across sessions and channels (hard discipline 1: nonce reuse with AES-GCM is catastrophic).
//!
//! Wire formats:
//! - Open blob: `base64(nonce12 || ct)` where the plaintext is JSON
//!   `{target_addr, target_port, groups, chan_salt}` sealed under `e2e_key` with a random nonce.
//!   Decrypting it authenticates the channel origin (only the key holder can seal).
//! - Data chunks: the stream is framed as `[u32 ct_len][ct]` blocks (the mux does not preserve
//!   chunk boundaries). Each block is one AEAD record under `chan_key` with
//!   `nonce = direction(1B) || 0*3 || seq(8B BE)`, seq starting at 0 per direction.
//!
//! Hard discipline 2: the receiver enforces a strictly increasing sequence per direction —
//! a replayed/reordered chunk fails the AEAD check against the expected nonce and the channel
//! must be torn down (fail closed; the relay cannot forge new ciphertexts but can replay old
//! ones, which must never surface as duplicated application-level mutations).

use crate::error::{Error, Result};
use crate::proto::message::E2eOpen;

use bytes::{Bytes, BytesMut};
use ring::{aead, hkdf};
use serde::{Deserialize, Serialize};
use std::io;
use std::pin::Pin;
use std::task::{Context, Poll};
use tokio::io::{AsyncRead, AsyncWrite, ReadBuf};

/// HKDF info for the per-channel sub-key.
pub const CHAN_INFO: &[u8] = b"chan";
/// Per-channel random salt length (bytes).
pub const CHAN_SALT_LEN: usize = 16;
/// Max plaintext per AEAD record (keeps sealed blocks well under the mux 256KB data cap).
pub const MAX_BLOCK: usize = 16 * 1024;
/// Anti-correlation padding bucket (guard profile G1②): a padded channel seals every record at
/// a multiple of this grain (random filler), so ciphertext record lengths stop correlating with
/// plaintext lengths. 0 = no padding (the default tier). The original length rides INSIDE the
/// sealed record as a 2-byte BE prefix (authenticated with the payload — the filler needs no
/// separate authentication, the AEAD tag already covers it).
pub const PAD_BUCKET: usize = 2048;
/// Length prefix of the original plaintext inside a padded record (u16 BE; MAX_BLOCK fits u16).
const PAD_LEN_PREFIX: usize = 2;

/// Split-tier config fetch (federation P3): a delegated consumer opens this reserved target
/// (E2E-sealed, port 0) to pull its token's effective rule vocabulary; the issuer answers
/// locally (never dialed, never ACL-gated — the working key is the authorization).
pub const DELEGATION_CONFIG_TARGET: &str = "__anet_delegation_config__";

/// Delegated admin channel (federation P3): bridges to the issuer's loopback admin API —
/// E2E-sealed end to end, so the bootstrap ticket never crosses a relay in plaintext.
pub const DELEGATION_ADMIN_TARGET: &str = "__anet_delegation_admin__";

/// Transit management prefix (federation P3): a blob target of `upstream:<node_name>` asks the
/// issuer (full-admin tokens only) to dial a discovered upstream's control endpoint through
/// the fan-out session — nested channel on the same mux, E2E on the consumer side only.
pub const DELEGATION_UPSTREAM_PREFIX: &str = "upstream:";

/// Entrust ID prefix (federation P3 entrust mode): an opaque, semantics-free routing word
/// (`en_<12 hex of token_hash>`). Hints with this prefix skip the relay's advertised-route
/// validation and ride the entrust registry instead — routing without rule disclosure (the
/// issuer no longer needs to push groups or advertise routes to issue an E2E delegation).
pub const ENTRUST_PREFIX: &str = "en_";

/// Derive the entrust ID of a token (deterministic: reproducible without extra storage, and the
/// same token registers the same ID across a failover set of relays).
pub fn entrust_id_of(token_hash: &str) -> String {
    format!("{}{}", ENTRUST_PREFIX, &token_hash[..12.min(token_hash.len())])
}

const NONCE_LEN: usize = 12;
const TAG_LEN: usize = 16;
const LEN_PREFIX: usize = 4;

struct Len32;
impl hkdf::KeyType for Len32 {
    fn len(&self) -> usize {
        32
    }
}

fn hkdf32(salt: &[u8], ikm: &[u8], info: &[u8]) -> [u8; 32] {
    let prk = hkdf::Salt::new(hkdf::HKDF_SHA256, salt).extract(ikm);
    let mut out = [0u8; 32];
    prk.expand(&[info], Len32)
        .and_then(|okm| okm.fill(&mut out))
        .expect("hkdf expand 32 bytes is infallible");
    out
}

/// Generate a fresh random E2E master key (issuer side, at issuance). The auth token is a
/// separate secret: deriving the E2E key from it would let a relay — which sees the token
/// plaintext at the entry hop — decrypt every envelope it forwards.
pub fn random_key() -> [u8; 32] {
    rand::random()
}

/// Decode a base64-encoded E2E master key (link `ek` word; 32 raw bytes).
pub fn key_from_b64(b64: &str) -> Option<[u8; 32]> {
    let raw = crate::util::base64_decode(b64)?;
    if raw.len() != 32 {
        return None;
    }
    raw.try_into().ok()
}

/// Key id carried in the E2E envelope: first 12 hex chars of the token SHA-256 hash
/// (48-bit space; issuer-side lookups are exact matches on these 12 chars).
pub fn kid_of(token_hash: &str) -> &str {
    token_hash.get(..12).unwrap_or(token_hash)
}

/// Per-channel sub-key (discipline 1: random salt per channel -> zero nonce reuse).
pub fn derive_chan_key(e2e_key: &[u8; 32], chan_salt: &[u8]) -> [u8; 32] {
    hkdf32(chan_salt, e2e_key, CHAN_INFO)
}

/// AEAD nonce: direction(1B) || 0*3 || seq(8B BE).
fn nonce(dir: u8, seq: u64) -> aead::Nonce {
    let mut n = [0u8; NONCE_LEN];
    n[0] = dir;
    n[4..].copy_from_slice(&seq.to_be_bytes());
    aead::Nonce::assume_unique_for_key(n)
}

fn less_safe(key: &[u8; 32]) -> aead::LessSafeKey {
    aead::LessSafeKey::new(aead::UnboundKey::new(&aead::AES_256_GCM, key).expect("32B key"))
}

/// Plaintext payload of an E2E Open blob.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct E2eOpenPayload {
    pub target_addr: String,
    pub target_port: u16,
    #[serde(default)]
    pub groups: Vec<String>,
    /// Base64 per-channel random salt.
    pub chan_salt: String,
}

/// Client side: seal an Open envelope for `target` and return it with the channel cipher
/// already initialized (send direction 0 = client -> issuer). `bucket` = padding grain
/// (0 = unpadded; see [`PAD_BUCKET`]).
///
/// CSPRNG note: `rand::random()` backs onto OsRng on every supported target. A future WASM
/// client build must re-verify entropy availability (getrandom's wasm backend) before sealing —
/// tracked in docs/todo/e2e.md §7.3.3.
#[allow(clippy::too_many_arguments)]
pub fn seal_open(
    e2e_key: &[u8; 32],
    kid: &str,
    hint: &str,
    target_addr: &str,
    target_port: u16,
    groups: &[String],
    bucket: usize,
) -> (E2eOpen, ChannelCipher) {
    let chan_salt: [u8; CHAN_SALT_LEN] = rand::random();    let payload = E2eOpenPayload {
        target_addr: target_addr.to_string(),
        target_port,
        groups: groups.to_vec(),
        chan_salt: crate::util::base64_encode(&chan_salt),
    };
    let plain = serde_json::to_vec(&payload).expect("E2eOpenPayload serialize");

    // random nonce per blob (multiple channels share e2e_key — a fixed blob nonce would be
    // cross-channel nonce reuse, the exact disaster discipline 1 exists to prevent)
    let blob_nonce: [u8; NONCE_LEN] = rand::random();
    let key = less_safe(e2e_key);
    let mut buf = plain;
    key.seal_in_place_append_tag(
        aead::Nonce::assume_unique_for_key(blob_nonce),
        aead::Aad::empty(),
        &mut buf,
    )
    .expect("seal into owned vec");

    let mut wire = Vec::with_capacity(NONCE_LEN + buf.len());
    wire.extend_from_slice(&blob_nonce);
    wire.extend_from_slice(&buf);

    let chan_key = derive_chan_key(e2e_key, &chan_salt);
    (
        E2eOpen {
            kid: kid.to_string(),
            hint: hint.to_string(),
            blob: crate::util::base64_encode(&wire),
        },
        ChannelCipher::with_bucket(chan_key, 0, bucket),
    )
}

/// Issuer side: unwrap an E2E envelope (kid already resolved to the token's e2e_key by the
/// caller). Decrypting successfully authenticates the channel origin — only a token holder
/// could seal the blob. Returns the plaintext payload and the channel cipher (send direction
/// 1 = issuer -> client). `bucket` mirrors the consumer's padding grain (from the token's
/// anti_correlate flag) so the unwrap side validates bucket alignment and strips the filler.
pub fn open_open(
    e2e_key: &[u8; 32],
    e2e: &E2eOpen,
    bucket: usize,
) -> Result<(E2eOpenPayload, ChannelCipher)> {
    let wire = crate::util::base64_decode(&e2e.blob)
        .ok_or_else(|| Error::Protocol("e2e blob is not valid base64".into()))?;
    if wire.len() < NONCE_LEN + TAG_LEN {
        return Err(Error::Protocol("e2e blob too short".into()));
    }
    let (nonce_bytes, ct) = wire.split_at(NONCE_LEN);
    let mut nonce_arr = [0u8; NONCE_LEN];
    nonce_arr.copy_from_slice(nonce_bytes);

    let key = less_safe(e2e_key);
    let mut buf = ct.to_vec();
    let plain = key
        .open_in_place(
            aead::Nonce::assume_unique_for_key(nonce_arr),
            aead::Aad::empty(),
            &mut buf,
        )
        .map_err(|_| Error::Auth("e2e blob authentication failed".into()))?;
    let payload: E2eOpenPayload = serde_json::from_slice(plain)
        .map_err(|e| Error::Protocol(format!("invalid e2e open payload: {e}")))?;

    let chan_salt = crate::util::base64_decode(&payload.chan_salt)
        .ok_or_else(|| Error::Protocol("invalid chan_salt".into()))?;
    if chan_salt.len() != CHAN_SALT_LEN {
        return Err(Error::Protocol("chan_salt length invalid".into()));
    }
    let chan_key = derive_chan_key(e2e_key, &chan_salt);
    Ok((payload, ChannelCipher::with_bucket(chan_key, 1, bucket)))
}

/// Per-channel AEAD record cipher with strict sequence enforcement (discipline 2).
///
/// `bucket` (guard profile G1②): when non-zero, every sealed record is padded with random
/// filler to a multiple of the bucket and the original length rides inside the sealed plaintext
/// as a u16 BE prefix — ciphertext record lengths stop correlating with plaintext lengths
/// (traffic-profile anti-correlation). Both ends derive the grain from the same token flag
/// (issuer: delegated_token.anti_correlate; consumer: the link's pad word), so no wire
/// negotiation exists — a mismatched pair fails closed on the receiver's alignment check.
pub struct ChannelCipher {
    key: aead::LessSafeKey,
    send_dir: u8,
    send_seq: u64,
    recv_seq: u64,
    bucket: usize,
}

impl ChannelCipher {
    /// `send_dir`: 0 on the client (client -> issuer), 1 on the issuer. Unpadded channel.
    pub fn new(chan_key: [u8; 32], send_dir: u8) -> Self {
        Self::with_bucket(chan_key, send_dir, 0)
    }

    /// Padded channel constructor (`bucket` = padding grain; 0 collapses to unpadded).
    pub fn with_bucket(chan_key: [u8; 32], send_dir: u8, bucket: usize) -> Self {
        Self {
            key: less_safe(&chan_key),
            send_dir,
            send_seq: 0,
            recv_seq: 0,
            bucket,
        }
    }

    /// Padding grain of this channel (0 = unpadded; framing layers enlarge their record-size
    /// cap accordingly).
    pub fn bucket(&self) -> usize {
        self.bucket
    }

    /// Build the padded plaintext frame: `[u16 BE orig_len][data][random filler]` sized to a
    /// whole multiple of the bucket. The AEAD tag covers the filler, so it needs no separate
    /// authentication; the original length must fit u16 (MAX_BLOCK keeps it well under).
    fn pad_frame(&self, plaintext: &[u8]) -> Result<Vec<u8>> {
        let orig = plaintext.len();
        if orig > u16::MAX as usize - PAD_LEN_PREFIX {
            return Err(Error::Protocol("e2e padded record too large".into()));
        }
        let total = (PAD_LEN_PREFIX + orig).div_ceil(self.bucket) * self.bucket;
        let mut frame = Vec::with_capacity(total);
        frame.extend_from_slice(&(orig as u16).to_be_bytes());
        frame.extend_from_slice(plaintext);
        let mut filled = frame.len();
        frame.resize(total, 0);
        while filled < total {
            let chunk: [u8; 32] = rand::random();
            let n = chunk.len().min(total - filled);
            frame[filled..filled + n].copy_from_slice(&chunk[..n]);
            filled += n;
        }
        Ok(frame)
    }

    /// Strip a padded frame back to the original plaintext (bucket alignment is verified —
    /// a malformed or mismatched-grain record fails closed).
    fn unpad_frame(&self, mut buf: Vec<u8>) -> Result<Vec<u8>> {
        if buf.len() < PAD_LEN_PREFIX || !buf.len().is_multiple_of(self.bucket) {
            return Err(Error::Protocol("e2e record not bucket-aligned".into()));
        }
        let orig = u16::from_be_bytes([buf[0], buf[1]]) as usize;
        if PAD_LEN_PREFIX + orig > buf.len() {
            return Err(Error::Protocol("e2e padded length out of range".into()));
        }
        buf.drain(..PAD_LEN_PREFIX);
        buf.truncate(orig);
        Ok(buf)
    }

    /// Seal one plaintext block into a framed record `[u32 ct_len][ct+tag]`.
    ///
    /// Sequence discipline: send_seq must never wrap (a u64 wrap would restart the nonce
    /// sequence — catastrophic for AES-GCM). The counter is physically unreachable within a
    /// channel's lifetime (2^64 records × 16KB); the check is belt-and-suspenders documentation
    /// of the contract, failing the channel instead of ever reusing a nonce.
    pub fn seal(&mut self, plaintext: &[u8]) -> Result<Vec<u8>> {
        if self.send_seq == u64::MAX {
            return Err(Error::Protocol("e2e send sequence exhausted".into()));
        }
        let payload: Vec<u8> = if self.bucket > 0 {
            self.pad_frame(plaintext)?
        } else {
            plaintext.to_vec()
        };
        // One allocation total: `[u32 ct_len][ciphertext][tag]`. The length prefix stays OUTSIDE
        // the AEAD record; the plaintext region is sealed in place and the tag appended separately
        // (ring's `seal_in_place_separate_tag` keeps the prefix bytes unencrypted).
        let mut out = Vec::with_capacity(LEN_PREFIX + payload.len() + TAG_LEN);
        out.extend_from_slice(&((payload.len() + TAG_LEN) as u32).to_be_bytes());
        out.extend_from_slice(&payload);
        let tag = self
            .key
            .seal_in_place_separate_tag(
                nonce(self.send_dir, self.send_seq),
                aead::Aad::empty(),
                &mut out[LEN_PREFIX..],
            )
            .expect("seal into owned vec");
        out.extend_from_slice(tag.as_ref());
        self.send_seq += 1;
        Ok(out)
    }

    /// Open one framed record. The record's implicit sequence number must equal the expected
    /// receive counter — any replay/reorder fails authentication and is fatal to the channel.
    pub fn open(&mut self, record: &[u8]) -> Result<Vec<u8>> {
        if self.recv_seq == u64::MAX {
            return Err(Error::Protocol("e2e receive sequence exhausted".into()));
        }
        let recv_dir = 1 - self.send_dir;
        let mut buf = record.to_vec();
        let plain_len = self
            .key
            .open_in_place(nonce(recv_dir, self.recv_seq), aead::Aad::empty(), &mut buf)
            .map_err(|_| Error::Protocol("e2e record authentication failed (replay?)".into()))?
            .len();
        self.recv_seq += 1;
        // Decrypted in place; drop the trailing tag and hand the buffer back directly (avoids a
        // second full copy of the plaintext on the read path).
        buf.truncate(plain_len);
        if self.bucket > 0 {
            return self.unpad_frame(buf);
        }
        Ok(buf)
    }
}

/// Stream wrapper applying E2E record encryption over any async stream (typically a MuxChannel).
///
/// Read path buffers incoming bytes, splits framed records and serves decrypted plaintext;
/// write path seals outgoing data into records (partial writes of a sealed record are tracked).
pub struct E2eStream<S> {
    inner: S,
    cipher: ChannelCipher,
    /// Undecoded inbound bytes (may contain a partial record).
    read_enc: BytesMut,
    /// Decrypted plaintext block being served (bytes, consumed offset).
    read_plain: Option<(Vec<u8>, usize)>,
    /// Sealed outbound record being flushed (bytes, written offset, accepted plaintext len).
    pending_write: Option<(Bytes, usize, usize)>,
    inner_eof: bool,
}

impl<S> E2eStream<S> {
    pub fn new(inner: S, cipher: ChannelCipher) -> Self {
        Self {
            inner,
            cipher,
            read_enc: BytesMut::with_capacity(2 * MAX_BLOCK),
            read_plain: None,
            pending_write: None,
            inner_eof: false,
        }
    }

    pub fn into_inner(self) -> S {
        self.inner
    }
}

impl<S: AsyncRead + Unpin> AsyncRead for E2eStream<S> {
    fn poll_read(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        loop {
            // serve decrypted plaintext first
            if let Some((plain, off)) = &mut self.read_plain {
                let avail = plain.len() - *off;
                if avail > 0 {
                    let n = buf.remaining().min(avail);
                    buf.put_slice(&plain[*off..*off + n]);
                    *off += n;
                    return Poll::Ready(Ok(()));
                }
                self.read_plain = None;
            }

            // try to decode one complete record from the ciphertext buffer
            if self.read_enc.len() >= LEN_PREFIX {
                let ct_len = u32::from_be_bytes([
                    self.read_enc[0],
                    self.read_enc[1],
                    self.read_enc[2],
                    self.read_enc[3],
                ]) as usize;
                // padded channels grow each record by the length prefix + at most one bucket of filler
                let filler = if self.cipher.bucket() > 0 {
                    PAD_LEN_PREFIX + self.cipher.bucket() - 1
                } else {
                    0
                };
                if ct_len > MAX_BLOCK + TAG_LEN + filler {
                    return Poll::Ready(Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "e2e record too large",
                    )));
                }
                if self.read_enc.len() >= LEN_PREFIX + ct_len {
                    let record = self.read_enc.split_to(LEN_PREFIX + ct_len);
                    let plain = self
                        .cipher
                        .open(&record[LEN_PREFIX..])
                        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;
                    self.read_plain = Some((plain, 0));
                    continue;
                }
            }

            if self.inner_eof {
                // Truncated tail ciphertext (a partial or undecodable record) is not a clean EOF —
                // surface it so an upper layer can't mistake a cut-short stream for complete data.
                if !self.read_enc.is_empty() {
                    return Poll::Ready(Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "e2e stream truncated mid-record",
                    )));
                }
                return Poll::Ready(Ok(())); // clean EOF with no pending plaintext
            }

            // need more ciphertext
            let mut chunk = [0u8; 16 * 1024];
            let mut rb = ReadBuf::new(&mut chunk);
            match Pin::new(&mut self.inner).poll_read(cx, &mut rb) {
                Poll::Ready(Ok(())) => {
                    let n = rb.filled().len();
                    if n == 0 {
                        self.inner_eof = true;
                    } else {
                        self.read_enc.extend_from_slice(rb.filled());
                    }
                }
                Poll::Ready(Err(e)) => return Poll::Ready(Err(e)),
                Poll::Pending => return Poll::Pending,
            }
        }
    }
}

impl<S: AsyncWrite + Unpin> AsyncWrite for E2eStream<S> {
    fn poll_write(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<io::Result<usize>> {
        // seal a new record only once the previous one is fully flushed (backpressure-safe:
        // the accepted plaintext length is fixed at seal time and reported on completion)
        if self.pending_write.is_none() {
            let block_len = buf.len().min(MAX_BLOCK);
            let sealed = self
                .cipher
                .seal(&buf[..block_len])
                .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e.to_string()))?;
            self.pending_write = Some((Bytes::from(sealed), 0, block_len));
        }

        let this = self.as_mut().get_mut(); // S: Unpin — field-level split borrows
        loop {
            {
                let (sealed, written, plain_len) = this.pending_write.as_ref().expect("just set");
                if *written == sealed.len() {
                    let n = *plain_len;
                    this.pending_write = None;
                    return Poll::Ready(Ok(n));
                }
            }
            let res = {
                let (sealed, written, _) = this.pending_write.as_ref().expect("pending");
                Pin::new(&mut this.inner).poll_write(cx, &sealed[*written..])
            };
            match res {
                Poll::Ready(Ok(0)) => {
                    return Poll::Ready(Err(io::Error::new(
                        io::ErrorKind::WriteZero,
                        "e2e inner write zero",
                    )))
                }
                Poll::Ready(Ok(n)) => {
                    this.pending_write.as_mut().expect("pending").1 += n;
                }
                Poll::Ready(Err(e)) => return Poll::Ready(Err(e)),
                Poll::Pending => return Poll::Pending,
            }
        }
    }

    fn poll_flush(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.inner).poll_flush(cx)
    }

    fn poll_shutdown(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.inner).poll_shutdown(cx)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_key() -> [u8; 32] {
        random_key()
    }

    #[test]
    fn key_roundtrip_b64_and_chan_key_domain_separation() {
        // keys are random (not derived from any token), and encode/decode via base64 losslessly
        let k1 = random_key();
        let k2 = random_key();
        assert_ne!(k1, k2);
        let b64 = crate::util::base64_encode(&k1);
        assert_eq!(key_from_b64(&b64), Some(k1));
        // malformed / wrong-length input fails closed
        assert_eq!(key_from_b64(""), None);
        assert_eq!(key_from_b64(&crate::util::base64_encode(b"short")), None);
        // channel sub-keys differ per salt
        let c1 = derive_chan_key(&k1, b"0123456789abcdef");
        let c2 = derive_chan_key(&k1, b"fedcba9876543210");
        assert_ne!(c1, c2);
    }

    #[test]
    fn open_blob_roundtrip() {
        let key = test_key();
        let hash = crate::util::sha256_hex(b"psk_test-token-0123456789");
        let (env, mut client_cipher) = seal_open(
            &key,
            kid_of(&hash),
            "git.internal",
            "10.0.0.5",
            5432,
            &["db".to_string()],
            0,
        );
        assert_eq!(env.kid, hash[..12]);
        assert_eq!(env.hint, "git.internal");

        let (payload, mut issuer_cipher) = open_open(&key, &env, 0).expect("unwrap");
        assert_eq!(payload.target_addr, "10.0.0.5");
        assert_eq!(payload.target_port, 5432);
        assert_eq!(payload.groups, vec!["db".to_string()]);

        // data plane: client -> issuer
        let rec = client_cipher.seal(b"SELECT 1").unwrap();
        let plain = issuer_cipher.open(&rec[LEN_PREFIX..]).unwrap();
        assert_eq!(plain, b"SELECT 1");
        // issuer -> client
        let rec = issuer_cipher.seal(b"row1").unwrap();
        let plain = client_cipher.open(&rec[LEN_PREFIX..]).unwrap();
        assert_eq!(plain, b"row1");
    }

    #[test]
    fn sequence_exhaustion_fails_closed() {
        // the nonce sequence must never wrap: at u64::MAX the channel dies instead of reusing one
        let key = test_key();
        let mut c = ChannelCipher::new(key, 0);
        c.send_seq = u64::MAX;
        assert!(c.seal(b"x").is_err());
        c.recv_seq = u64::MAX;
        assert!(c.open(b"xxxx").is_err());
    }

    #[test]
    fn wrong_key_cannot_unwrap() {
        let (env, _) = seal_open(&test_key(), "kid", "h", "a", 1, &[], 0);
        let wrong = random_key();
        assert!(open_open(&wrong, &env, 0).is_err());
    }

    #[test]
    fn replayed_record_rejected() {
        let key = test_key();
        let (env, mut a) = seal_open(&key, "kid", "h", "a", 1, &[], 0);
        let (_, mut b) = open_open(&key, &env, 0).unwrap();
        let rec1 = a.seal(b"first").unwrap();
        let rec2 = a.seal(b"second").unwrap();
        // out-of-order delivery: the later record fails against the expected sequence 0
        assert!(b.open(&rec2[LEN_PREFIX..]).is_err());
        // a failed open must not advance the sequence (legitimate in-order record still passes)
        b.open(&rec1[LEN_PREFIX..]).unwrap();
        // replaying an old record is rejected (strict sequence, discipline 2)
        assert!(b.open(&rec1[LEN_PREFIX..]).is_err());
        // the live next record still passes afterwards
        b.open(&rec2[LEN_PREFIX..]).unwrap();
    }

    #[tokio::test]
    async fn e2e_stream_roundtrip_over_duplex() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let key = test_key();
        let (env, client_cipher) = seal_open(&key, "kid", "h", "a", 1, &[], 0);
        let (_, issuer_cipher) = open_open(&key, &env, 0).unwrap();

        let (s1, s2) = tokio::io::duplex(64 * 1024);
        let mut client = E2eStream::new(s1, client_cipher);
        let mut issuer = E2eStream::new(s2, issuer_cipher);

        let payload = vec![b'x'; 100_000]; // spans many records
        let writer = tokio::spawn(async move {
            client.write_all(&payload).await.unwrap();
            client.shutdown().await.unwrap();
        });
        let mut got = Vec::new();
        issuer.read_to_end(&mut got).await.unwrap();
        writer.await.unwrap();
        assert_eq!(got, vec![b'x'; 100_000]);
    }

    /// Guard profile G1②: bucket padding hides plaintext lengths — every sealed record is a
    /// whole multiple of the bucket, the unwrap side restores the exact original, and a grain
    /// mismatch (or a tampered frame) fails closed.
    #[test]
    fn e2e_padding_bucket_roundtrip() {
        let key = test_key();
        let (env, mut sender) = seal_open(&key, "kid", "h", "a", 1, &[], PAD_BUCKET);
        let (_, mut receiver) = open_open(&key, &env, PAD_BUCKET).unwrap();

        for plain_len in [1usize, 100, PAD_BUCKET - 2, PAD_BUCKET - 1, PAD_BUCKET, 5 * PAD_BUCKET / 2] {
            let plain: Vec<u8> = (0..plain_len).map(|i| (i % 251) as u8).collect();
            let rec = sender.seal(&plain).unwrap();
            // sealed body (ct incl. tag) is bucket-aligned + tag; the filler hides the length
            let body_len = rec.len() - LEN_PREFIX;
            assert_eq!(
                (body_len - TAG_LEN) % PAD_BUCKET,
                0,
                "padded plaintext must be a bucket multiple (len {plain_len})"
            );
            // two same-bucket plaintexts of different lengths produce equal record sizes
            let got = receiver.open(&rec[LEN_PREFIX..]).unwrap();
            assert_eq!(got, plain, "unwrap restores the exact original (len {plain_len})");
        }

        // small and large plaintexts of the same bucket produce identical record lengths
        let r1 = sender.seal(b"a").unwrap();
        let r2 = sender.seal(&vec![b'b'; PAD_BUCKET - 10]).unwrap();
        assert_eq!(r1.len(), r2.len(), "length correlation removed within a bucket");

        // grain mismatch: a receiver without the bucket sees the raw framed body (not the
        // plain) — both ends must derive the grain from the same token flag. Fresh channel so
        // the strict receive sequence starts at 0 for both receivers.
        let key_m = test_key();
        let (env_m, mut sender_m) = seal_open(&key_m, "kid-m", "h", "a", 1, &[], PAD_BUCKET);
        let (_, mut padded_m) = open_open(&key_m, &env_m, PAD_BUCKET).unwrap();
        let (_, mut unpadded_m) = open_open(&key_m, &env_m, 0).unwrap();
        let rec_m = sender_m.seal(b"payload-x").unwrap();
        let raw = unpadded_m.open(&rec_m[LEN_PREFIX..]).unwrap();
        assert_ne!(raw, b"payload-x", "unpadded receiver sees the framed body, not the plain");
        assert_eq!(&raw[2..2 + 9], b"payload-x", "frame = [u16 len][data][filler]");
        assert!(padded_m.open(&rec_m[LEN_PREFIX..]).is_ok());

        // a tampered record (alignment broken) fails closed on the padded receiver
        let (env2, mut sender2) = seal_open(&key, "kid2", "h", "a", 1, &[], PAD_BUCKET);
        let (_, mut receiver2) = open_open(&key, &env2, PAD_BUCKET).unwrap();
        let rec = sender2.seal(b"tamper-me").unwrap();
        let orig_ct = rec.len() - LEN_PREFIX - TAG_LEN;
        // shrink the record by one byte — no longer bucket-aligned
        let truncated: Vec<u8> = rec[..LEN_PREFIX + orig_ct - 1 + TAG_LEN].to_vec();
        assert!(receiver2.open(&truncated[LEN_PREFIX..]).is_err());
    }

    /// Padded E2eStream end to end: the stream layer seals/opens bucket frames transparently
    /// and its record-size cap admits the padded growth.
    #[tokio::test]
    async fn e2e_stream_padded_roundtrip() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let key = test_key();
        let (env, client_cipher) = seal_open(&key, "kid", "h", "a", 1, &[], PAD_BUCKET);
        let (_, issuer_cipher) = open_open(&key, &env, PAD_BUCKET).unwrap();

        let (s1, s2) = tokio::io::duplex(64 * 1024);
        let mut client = E2eStream::new(s1, client_cipher);
        let mut issuer = E2eStream::new(s2, issuer_cipher);

        let payload = vec![b'y'; 37_000]; // spans buckets of uneven sizes
        let writer = tokio::spawn(async move {
            client.write_all(&payload).await.unwrap();
            client.shutdown().await.unwrap();
        });
        let mut got = Vec::new();
        issuer.read_to_end(&mut got).await.unwrap();
        writer.await.unwrap();
        assert_eq!(got, vec![b'y'; 37_000]);
    }
}
